45	struct BandwidthTable {
46	    double GM_TO_UB = 0.0;
47	    double GM_TO_L1 = 0.0;
48	    double UB_TO_GM = 0.0;
49	    double L1_TO_GM = 0.0;
50	    double UB_TO_UB = 0.0;
