57	    double L1_FILL = 0.0;
58	
59	    constexpr double operator[](PipeKey key) const
60	    {
61	        switch (key) {
62	            case PipeKey::VECTOR:
63	            case PipeKey::CUBE:
64	            case PipeKey::COUNT:
65	                return 0.0;
66	            case PipeKey::GM_TO_UB:
67	                return GM_TO_UB;
68	            case PipeKey::GM_TO_L1:
69	                return GM_TO_L1;
70	            case PipeKey::UB_TO_GM:
71	                return UB_TO_GM;
72	            case PipeKey::L1_TO_GM:
73	                return L1_TO_GM;
74	            case PipeKey::UB_TO_UB:
