127	inline constexpr std::array<bool, static_cast<std::size_t>(PipeKey::COUNT)> BuildBandwidthProvided(
128	    const BandwidthTable& bandwidth)
129	{
130	    std::array<bool, static_cast<std::size_t>(PipeKey::COUNT)> provided{};
131	    provided[static_cast<std::size_t>(PipeKey::GM_TO_UB)] = (bandwidth.GM_TO_UB > 0.0);
132	    provided[static_cast<std::size_t>(PipeKey::GM_TO_L1)] = (bandwidth.GM_TO_L1 > 0.0);
133	    provided[static_cast<std::size_t>(PipeKey::UB_TO_GM)] = (bandwidth.UB_TO_GM > 0.0);
134	    provided[static_cast<std::size_t>(PipeKey::L1_TO_GM)] = (bandwidth.L1_TO_GM > 0.0);
135	    provided[static_cast<std::size_t>(PipeKey::UB_TO_UB)] = (bandwidth.UB_TO_UB > 0.0);
136	    provided[static_cast<std::size_t>(PipeKey::L0C_TO_GM)] = (bandwidth.L0C_TO_GM > 0.0);
137	    provided[static_cast<std::size_t>(PipeKey::L0C_TO_L1)] = (bandwidth.L0C_TO_L1 > 0.0);
138	    provided[static_cast<std::size_t>(PipeKey::L1_TO_L0A)] = (bandwidth.L1_TO_L0A > 0.0);
139	    provided[static_cast<std::size_t>(PipeKey::L1_TO_L0B)] = (bandwidth.L1_TO_L0B > 0.0);
140	    provided[static_cast<std::size_t>(PipeKey::L1_TO_BT)] = (bandwidth.L1_TO_BT > 0.0);
141	    provided[static_cast<std::size_t>(PipeKey::L1_TO_FB)] = (bandwidth.L1_TO_FB > 0.0);
142	    provided[static_cast<std::size_t>(PipeKey::L1_FILL)] = (bandwidth.L1_FILL > 0.0);
143	    return provided;
144	}
