146	inline thread_local long double gPredictFrequencyMHz = GetDefaultArchConfig().frequency_hz / kMicrosPerSecond;
147	inline thread_local BandwidthTable gPredictBandwidthBytesPerUs = GetDefaultArchConfig().bandwidth;
148	inline thread_local std::array<bool, static_cast<std::size_t>(PipeKey::COUNT)> gPredictBandwidthProvided =
149	    BuildBandwidthProvided(gPredictBandwidthBytesPerUs);
