151	inline void SetPredictFrequencyAndBandwidth(long double frequencyMhz, const BandwidthTable& bandwidth)
152	{
153	    gPredictFrequencyMHz = frequencyMhz;
154	    gPredictBandwidthBytesPerUs = bandwidth;
155	    gPredictBandwidthProvided = BuildBandwidthProvided(bandwidth);
156	}
