167	inline bool HasPredictBandwidthBytesPerUs(PipeKey key)
168	{
169	    if (!IsMemoryPipe(key)) {
170	        return false;
171	    }
172	    return gPredictBandwidthProvided[static_cast<std::size_t>(key)];
173	}
