177	// ---------------------------------------------------------------------------
178	// Hill bandwidth model (single-transfer size saturation + multi-core cap).
179	//   hill_bw(B) = peak * B / (K + B)                       [GiB/s], saturates at peak
180	//   bw_eff(B,n) = min(hill_bw(B), total_group / n)        external GM pipes contend
181	//     read  group {GM_TO_UB, GM_TO_L1}      -> total_read
182	//     write group {UB_TO_GM, L1_TO_GM, L0C_TO_GM} -> total_write
183	//   cycle(B,n) = (B / kBytesPerGb) / bw_eff(B,n) * kMainFrequencyHz
184	// Default model: K=0 (=> hill=peak, constant) + totals<=0 (=> no cap) == the legacy
185	// flat `bytes / bandwidth[PipeKey]` model. Fitted Hill params are applied via env
186	// PTO_BW_MODE=fitted (see ApplyHillBandwidthFromEnv). Backward compatible.
187	// ---------------------------------------------------------------------------
188	inline constexpr bool IsExternalGmPipe(PipeKey key)
189	{
190	    return key == PipeKey::GM_TO_UB || key == PipeKey::GM_TO_L1 || key == PipeKey::UB_TO_GM ||
191	           key == PipeKey::L1_TO_GM || key == PipeKey::L0C_TO_GM;
192	}
193	
194	struct HillBandwidthModel {
195	    double peak_gibs[static_cast<std::size_t>(PipeKey::COUNT)] = {0.0};
196	    double k_bytes[static_cast<std::size_t>(PipeKey::COUNT)] = {0.0};
197	    double total_read_gibs = 0.0;  // <=0 means no read cap
198	    double total_write_gibs = 0.0; // <=0 means no write cap
199	
200	    double HillBw(PipeKey key, uint64_t bytes) const
201	    {
202	        const auto i = static_cast<std::size_t>(key);
203	        const double peak = peak_gibs[i];
204	        const double k = k_bytes[i];
205	        const double denom = k + static_cast<double>(bytes);
206	        if (denom <= 0.0) {
207	            return peak; // bytes==0, K==0 -> any finite bw (cycle computed as 0)
208	        }
209	        return peak * static_cast<double>(bytes) / denom;
210	    }
211	
212	    double GroupTotal(PipeKey key) const
213	    {
214	        if (key == PipeKey::GM_TO_UB || key == PipeKey::GM_TO_L1) {
215	            return total_read_gibs;
216	        }
217	        if (key == PipeKey::UB_TO_GM || key == PipeKey::L1_TO_GM || key == PipeKey::L0C_TO_GM) {
218	            return total_write_gibs;
219	        }
220	        return 0.0; // internal pipe: no GM contention
221	    }
222	
223	    double BwEff(PipeKey key, uint64_t bytes, uint32_t ncores) const
224	    {
225	        double bw = HillBw(key, bytes);
226	        if (IsExternalGmPipe(key)) {
227	            const double total = GroupTotal(key);
228	            if (total > 0.0 && ncores > 0) {
229	                const double cap = total / static_cast<double>(ncores);
230	                if (cap < bw) {
231	                    bw = cap;
232	                }
233	            }
234	        }
235	        return bw;
236	    }
237	};
238	
239	// Build the legacy flat model (peak = current table constant, K = 0, no cap).
240	inline HillBandwidthModel MakeFlatHillModel()
241	{
242	    const BandwidthTable& b = GetDefaultArchConfig().bandwidth;
243	    HillBandwidthModel m;
244	    m.peak_gibs[static_cast<std::size_t>(PipeKey::GM_TO_UB)] = b.GM_TO_UB;
245	    m.peak_gibs[static_cast<std::size_t>(PipeKey::GM_TO_L1)] = b.GM_TO_L1;
246	    m.peak_gibs[static_cast<std::size_t>(PipeKey::UB_TO_GM)] = b.UB_TO_GM;
247	    m.peak_gibs[static_cast<std::size_t>(PipeKey::L1_TO_GM)] = b.L1_TO_GM;
248	    m.peak_gibs[static_cast<std::size_t>(PipeKey::UB_TO_UB)] = b.UB_TO_UB;
249	    m.peak_gibs[static_cast<std::size_t>(PipeKey::L0C_TO_GM)] = b.L0C_TO_GM;
250	    m.peak_gibs[static_cast<std::size_t>(PipeKey::L0C_TO_L1)] = b.L0C_TO_L1;
251	    m.peak_gibs[static_cast<std::size_t>(PipeKey::L1_TO_L0A)] = b.L1_TO_L0A;
252	    m.peak_gibs[static_cast<std::size_t>(PipeKey::L1_TO_L0B)] = b.L1_TO_L0B;
253	    m.peak_gibs[static_cast<std::size_t>(PipeKey::L1_TO_BT)] = b.L1_TO_BT;
254	    m.peak_gibs[static_cast<std::size_t>(PipeKey::L1_TO_FB)] = b.L1_TO_FB;
255	    m.peak_gibs[static_cast<std::size_t>(PipeKey::L1_FILL)] = b.L1_FILL;
256	    return m; // K=0, totals=0 -> exact legacy flat behaviour
257	}
258	
259	// Fitted Hill params — pure on-device B3 fit (see tools/bandwidth_fit/hill_params.json).
260	// The CAModel (B1) per-event signal was found to disagree with B3 and is NOT used:
261	// pure-B3 is strictly better in-fit (0.136 vs 0.227) and LOO (0.303 vs 0.364), and fixes
262	// GM_TO_L1's systematic 0.70x low bias of the mixed fit.
263	// Caps left at 0 (no cap): FA at n<=4 with small tiles shows no observable GM contention.
264	inline HillBandwidthModel MakeFittedHillModel()
265	{
266	    HillBandwidthModel m = MakeFlatHillModel();
267	    // Per-pipe fitted params: peak bandwidth (GiB/s) and half-saturation size (k_bytes).
268	    constexpr double kGmToUbPeakGiBs = 247.16;
269	    constexpr double kGmToUbKBytes = 30643.0;
270	    constexpr double kGmToL1PeakGiBs = 28.61;
271	    constexpr double kGmToL1KBytes = 1107.0;
272	    constexpr double kUbToGmPeakGiBs = 28.19;
273	    constexpr double kUbToGmKBytes = 1755.0;
274	    constexpr double kL0cToGmPeakGiBs = 41.25;
275	    constexpr double kL0cToGmKBytes = 29104.0;
276	    auto set = [&](PipeKey k, double peak, double kb) {
277	        m.peak_gibs[static_cast<std::size_t>(k)] = peak;
278	        m.k_bytes[static_cast<std::size_t>(k)] = kb;
279	    };
280	    set(PipeKey::GM_TO_UB, kGmToUbPeakGiBs, kGmToUbKBytes);
281	    set(PipeKey::GM_TO_L1, kGmToL1PeakGiBs, kGmToL1KBytes);
282	    set(PipeKey::UB_TO_GM, kUbToGmPeakGiBs, kUbToGmKBytes);
283	    set(PipeKey::L0C_TO_GM, kL0cToGmPeakGiBs, kL0cToGmKBytes);
284	    return m;
285	}
286	
287	inline thread_local HillBandwidthModel gHillBandwidth = MakeFlatHillModel();
288	inline thread_local uint32_t gActiveCoreCount = 1;
289	inline thread_local bool gHillBandwidthApplied = false;
290	
291	inline void SetHillBandwidthModel(const HillBandwidthModel& m) { gHillBandwidth = m; }
292	
293	inline void ResetHillBandwidthModel()
294	{
295	    gHillBandwidth = MakeFlatHillModel();
296	    gActiveCoreCount = 1;
297	    gHillBandwidthApplied = true; // explicit reset suppresses env auto-apply
298	}
299	
300	inline void SetActiveCoreCount(uint32_t n) { gActiveCoreCount = n > 0 ? n : 1; }
301	
302	// PTO_BW_MODE: "" / "flat" = legacy flat; "fitted" = fitted Hill params. Applied once.
303	inline void ApplyHillBandwidthFromEnv()
304	{
305	    if (gHillBandwidthApplied) {
306	        return;
307	    }
308	    gHillBandwidthApplied = true;
309	    const char* mode = std::getenv("PTO_BW_MODE");
310	    if (mode != nullptr && std::string_view(mode) == "fitted") {
311	        gHillBandwidth = MakeFittedHillModel();
312	    }
313	}
314	
315	inline long double CyclesToUs(uint64_t cycles, long double frequencyMhz)
316	{
317	    if (frequencyMhz <= 0.0L) {
318	        return 0.0L;
319	    }
320	    return static_cast<long double>(cycles) / frequencyMhz;
321	}
322	
323	inline long double CyclesToUs(uint64_t cycles) { return CyclesToUs(cycles, GetPredictFrequencyMHz()); }
324	
325	inline long double TransferBytesToUs(uint64_t bytes, double bandwidthBytesPerUs)
326	{
327	    if (bytes == 0) {
328	        return 0.0L;
329	    }
330	    if (bandwidthBytesPerUs <= 0.0) {
331	        return std::numeric_limits<long double>::quiet_NaN();
332	    }
333	    return static_cast<long double>(bytes) / static_cast<long double>(bandwidthBytesPerUs);
334	}
335	
336	inline long double TransferBytesToUs(uint64_t bytes, PipeKey pipe)
337	{
338	    if (!HasPredictBandwidthBytesPerUs(pipe)) {
339	        return std::numeric_limits<long double>::quiet_NaN();
340	    }
341	    return TransferBytesToUs(bytes, GetPredictBandwidthBytesPerUs(pipe));
342	}
343	
344	} // namespace pto::mocker::evaluator
345	
346	#endif
