127	inline void CollectStuckEntries(const std::vector<PipeQueue> &queues, PipeTimeline &timeline)
128	{
129	    for (auto &queue : queues) {
130	        for (auto &entry : queue.entries)
131	            timeline.events.push_back(BuildPipeEvent(entry, queue.label, true));
132	    }
133	}
