137	
138	inline event_t EncodeMergedSyncEvent(const SyncRecord &sync, bool cross_core_enabled)
139	{
140	    if (cross_core_enabled && sync.cross_core) {
141	        return CROSS_CHANNEL_OFFSET + sync.event_id;
142	    }
143	    return EncodeSyncKey(sync.dst_pipe, sync.event_id, sync.subblock_id);
