165	    if (!sync.cross_core && sync.subblock_id == 0 && IsCubeSidePipe(sync.src_pipe) && !IsCubeSidePipe(sync.dst_pipe)) {
166	        AppendExtraSignal(pipe_entry, EncodeSyncKey(sync.dst_pipe, sync.event_id, 1));
