187	inline void PushInstrEntry(std::vector<PipeQueue> &queues, const MergedEntry &entry, PipeStage &last_mte2,
188	                           bool include_seq, CvDependencyState &cv_state)
189	{
190	    int idx = QueueIndex(entry.instr.stage, entry.instr.subblock_id);
191	    if (idx < 0 || idx >= static_cast<int>(queues.size())) {
192	        return;
193	    }
194	    if (IsMTE2(entry.instr.stage)) {
195	        last_mte2 = entry.instr.stage;
196	    }
197	    cv_state.ObserveProducer(entry.instr);
198	    queues[idx].Push(BuildInstrEntry(entry.instr, entry.seq, include_seq, cv_state));
