201	inline void PushMergedEntry(std::vector<PipeQueue> &queues, const MergedEntry &entry, PipeStage &last_mte2,
202	                            bool include_seq, bool cross_core_enabled, CvDependencyState &cv_state)
203	{
204	    if (!entry.is_sync) {
205	        PushInstrEntry(queues, entry, last_mte2, include_seq, cv_state);
206	        return;
207	    }
208	    switch (entry.sync.kind) {
209	        case SyncKind::Barrier:
210	            PushBarrierEntry(queues);
211	            break;
212	        case SyncKind::Signal:
213	            PushSignalEntry(queues, entry, last_mte2, include_seq, cross_core_enabled);
214	            break;
215	        case SyncKind::Wait:
216	            PushWaitEntry(queues, entry, last_mte2, include_seq, cross_core_enabled);
217	            break;
218	    }
219	}
