241	// ── Event-driven Step simulation with cache ──
242	
243	inline PipeTimeline StepSimulate(std::vector<PipeQueue> &queues, std::vector<EventChannel> &channels,
244	                                 L2CacheModel &cache, uint32_t max_steps = 500000)
245	{
246	    PipeTimeline result;
247	    uint64_t now = 0;
248	
249	    for (uint32_t step = 0; step < max_steps; ++step) {
250	        StepProgress progress;
251	        for (auto &queue : queues)
252	            CompleteRunningEntry(queue, result, channels, now, progress);
253	
254	        PopDoneEntries(queues);
255	
256	        for (auto &queue : queues)
257	            TryDispatchSingleCore(queue, channels, cache, now, progress);
258	
259	        if (!progress.any_active)
260	            break;
261	        if (!progress.dispatched) {
262	            if (!AnyRunning(queues))
263	                break;
264	            if (progress.next_event != UINT64_MAX && progress.next_event > now)
265	                now = progress.next_event;
266	        }
267	    }
268	
269	    CollectStuckEntries(queues, result);
270	
271	    for (auto &ev : result.events)
272	        result.total_cycles = std::max(result.total_cycles, ev.end_cycle);
273	    return result;
274	}
