292	// Helper: lookup EventChannel for multi-core simulation
293	inline EventChannel *LookupChannel(std::vector<EventChannel> &intra, std::vector<EventChannel> &cross, uint32_t core_id,
294	                                   event_t event_id)
295	{
296	    if (event_id < 0)
297	        return nullptr;
298	    if (event_id >= CROSS_CHANNEL_OFFSET) {
299	        int idx = event_id - CROSS_CHANNEL_OFFSET;
300	        if (idx < static_cast<int>(cross.size()))
301	            return &cross[idx];
302	        return nullptr;
303	    }
304	    int idx = core_id * EVENTS_PER_CORE + event_id;
305	    if (idx < static_cast<int>(intra.size()))
306	        return &intra[idx];
307	    return nullptr;
308	}
