346	inline bool MultiCoreWaitsReady(const PipeEntry &entry, uint32_t core_id, std::vector<EventChannel> &intra_channels,
347	                                std::vector<EventChannel> &cross_channels)
348	{
349	    for (int i = 0; i < entry.wait_count; ++i) {
350	        auto *channel = LookupChannel(intra_channels, cross_channels, core_id, entry.wait_events[i]);
351	        if (channel && !channel->signaled())
