371	inline void TryDispatchMultiCore(CorePipeline &core, PipeQueue &queue, std::vector<EventChannel> &intra_channels,
372	                                 std::vector<EventChannel> &cross_channels, L2CacheModel &cache, uint64_t now,
373	                                 StepProgress &progress)
374	{
375	    if (!queue.CanAccept() || queue.entries.empty())
376	        return;
377	    auto &entry = queue.entries.front();
378	    if (entry.name == "BARRIER") {
379	        StartEntry(queue, entry, now, cache, progress);
380	        return;
381	    }
382	    if (entry.wait_count > 0 && entry.state == PipeEntry::WAITING) {
383	        if (!MultiCoreWaitsReady(entry, core.core_id, intra_channels, cross_channels)) {
384	            progress.any_active = true;
385	            return;
386	        }
387	        ConsumeMultiCoreSyncWaits(entry, core.core_id, intra_channels, cross_channels);
388	        entry.state = PipeEntry::IDLE;
389	    }
390	    if (entry.state == PipeEntry::IDLE)
391	        StartEntry(queue, entry, now, cache, progress);
