74	
75	struct InstrRecord {
76	    std::string opcode;    // "TLOAD", "TADD", ...
77	    std::string dtype;     // "fp16", "fp32", "int8", ...
78	    std::string tile_args; // stringified tile arguments, e.g. "ub_out, ub_a, ub_b"
79	    int rows = 0;
80	    int cols = 0;
81	    uint64_t estimated_cycles = 0;
82	    PipeStage stage = PipeStage::Vector;
83	    static constexpr int MAX_WAIT_EVENTS = 8;
84	    event_t signal_event = -1;
85	    event_t wait_events[MAX_WAIT_EVENTS] = {-1, -1, -1, -1, -1, -1, -1, -1};
86	    int wait_count = 0;
87	    static constexpr int MAX_SYNC_SIGNALS = 8;
88	    event_t extra_sync_signals[MAX_SYNC_SIGNALS] = {-1, -1, -1, -1, -1, -1, -1, -1};
