99	struct SyncRecord {
100	    SyncKind kind;
101	    event_t event_id = -1;
102	    int src_pipe = -1;
103	    int dst_pipe = -1;
104	    bool cross_core = false;
105	    uint64_t seq = 0;         // global sequence number for merge ordering
106	    uint32_t core_id = 0;     // recording core
107	    uint32_t subblock_id = 0; // VecCore index (0 or 1)
108	};
