110	// ── Shared global sequence counter (preserves ordering across recorders) ──
111	
112	inline uint64_t SharedNextSeq()
113	{
114	    static thread_local uint64_t counter = 0;
115	    return counter++;
116	}
117	
118	template <typename Record>
119	class CoreRecordStorage {
120	public:
121	    static std::vector<std::vector<Record>>& AllCoreRecords()
122	    {
123	        static thread_local std::vector<std::vector<Record>> per_core;
124	        return per_core;
125	    }
126	
127	    static std::vector<Record>& GetForCore(uint32_t core_id)
128	    {
129	        auto& all = AllCoreRecords();
130	        if (core_id >= all.size())
131	            all.resize(core_id + 1);
132	        return all[core_id];
133	    }
134	
135	    static std::vector<Record>& Get() { return GetForCore(ActiveCore()); }
136	
137	    static void SetActiveCore(uint32_t id)
138	    {
139	        ActiveCoreRef() = id;
140	        GetForCore(id);
141	    }
142	
143	    static uint32_t ActiveCore() { return ActiveCoreRef(); }
144	
145	    static void Clear()
146	    {
147	        AllCoreRecords().clear();
148	        AllCoreRecords().resize(1);
149	    }
150	
151	private:
152	    static uint32_t& ActiveCoreRef()
153	    {
154	        static thread_local uint32_t id = 0;
155	        return id;
156	    }
157	};
