293	// ── Compile-time tile traits (duck typing for pto::Tile<...>) ──
294	
295	template <typename T>
296	struct TileTraits {
297	    static constexpr int rows = 0;
298	    static constexpr int cols = 0;
299	    static constexpr const char* dtype_str() { return "unknown"; }
300	};
301	
302	template <typename T>
303	concept HasTileDims = requires {
304	    typename T::DType;
305	    { T::Rows } -> std::convertible_to<int>;
306	    { T::Cols } -> std::convertible_to<int>;
307	};
308	
309	template <HasTileDims T>
310	struct TileTraits<T> {
311	    using DType = typename T::DType;
312	    static constexpr int rows = T::Rows;
313	    static constexpr int cols = T::Cols;
314	
315	    static constexpr const char* dtype_str()
316	    {
317	        if constexpr (std::is_same_v<DType, float>)
318	            return "fp32";
319	        else if constexpr (std::is_same_v<DType, int32_t>)
320	            return "int32";
321	        else if constexpr (std::is_same_v<DType, uint32_t>)
322	            return "uint32";
323	        else if constexpr (std::is_same_v<DType, int16_t>)
324	            return "int16";
325	        else if constexpr (std::is_same_v<DType, uint16_t>)
326	            return "uint16";
327	        else if constexpr (std::is_same_v<DType, int8_t>)
328	            return "int8";
329	        else if constexpr (std::is_same_v<DType, uint8_t>)
330	            return "uint8";
331	        else
332	            return "fp16";
333	    }
334	};
