100	template <typename T, typename T2, typename... Rest>
101	inline void ExtractFirstTileInfo(int& rows, int& cols, std::string& dtype, T&& first, T2&& second, Rest&&... rest)
102	{
103	    if (!TryTileInfo(rows, cols, dtype, std::forward<T>(first))) {
104	        ExtractFirstTileInfo(rows, cols, dtype, std::forward<T2>(second), std::forward<Rest>(rest)...);
105	    }
