108	inline void RecordInstr(const char* opcode, auto&& first_tile, auto&&... rest_tiles)
109	{
110	    // Look up pipeline stage from opcode name and tile types (TLOAD/TSTORE need tile routing)
111	    perf_sim::PipeStage stage = perf_sim::ResolvePipeStageArgs(opcode, first_tile, rest_tiles...);
112	
113	    // 1. Track data dependencies (cross-pipe waits + signal event for this instr)
114	    auto dep = perf_sim::TileDepTracker::TrackByAddr(opcode, stage, first_tile, rest_tiles...);
115	
116	    // 2. Build InstrRecord
117	    perf_sim::InstrRecord r;
118	    r.opcode = opcode;
119	    r.stage = stage;
120	    r.signal_event = dep.signal_event;
121	    for (int i = 0; i < dep.wait_count && i < perf_sim::InstrRecord::MAX_WAIT_EVENTS; ++i) {
122	        r.wait_events[i] = dep.wait_events[i];
123	    }
124	    r.wait_count = dep.wait_count;
125	
126	    // Tile dimensions + dtype: try each tile argument in order, use first one with info.
127	    // For TSTORE(dst=GlobalData, src=TileData), this skips GlobalData and uses TileData.
128	    ExtractFirstTileInfo(r.rows, r.cols, r.dtype, first_tile, rest_tiles...);
129	
130	    const uint64_t measured_cycles = GetLastPtoInstrCycles();
131	    const uint64_t estimated_cycles =
132	        perf_sim::EstimateInstrCycles(opcode, r.rows, r.cols, r.dtype.empty() ? "unknown" : r.dtype.c_str());
133	    uint64_t cycles = measured_cycles;
134	    const bool useEstimatedCycles = cycles == 0 ||
135	                                    (std::string_view(opcode) == "TROWEXPAND" && estimated_cycles > cycles) ||
136	                                    (std::string_view(opcode) == "TDIVS" && (r.dtype == "int16" || r.dtype == "int32"));
137	    if (useEstimatedCycles) {
138	        cycles = estimated_cycles;
139	        auto& trace = ::pto::mocker::GetMutableTrace();
140	        if (!trace.executed_pto.empty()) {
141	            trace.executed_pto.back().total_cycles = cycles;
142	        }
143	    }
144	    r.estimated_cycles = cycles;
145	
146	    perf_sim::CvSyncRecorder::ApplyPending(opcode, r);
147	    perf_sim::PtoRecorder::Record(std::move(r));
148	}
