13	class PerfSimReporter {
14	public:
15	    // Fixed track layout for Chrome Trace (1AIC + 2AIV per core)
16	    struct TrackInfo {
17	        const char *tid;          // queue label (must match PipeQueue label)
18	        std::string display_name; // [AIC-{core_id}] PIPE or [AIV-{sub}] PIPE
