22	    static std::vector<TrackInfo> GetTracksForCore(uint32_t core_id)
23	    {
24	        std::string aic = "[AIC-" + std::to_string(core_id) + "] ";
25	        std::string aiv0 = "[AIC-" + std::to_string(core_id) + "/AIV-0] ";
