28	            {"Scalar", aic + "Scalar", "AIC"},      {"MTE2_AIC", aic + "MTE2", "AIC"},
29	            {"MTE1", aic + "MTE1", "AIC"},          {"CUBE", aic + "CUBE", "AIC"},
30	            {"FIXP", aic + "FIXP", "AIC"},          {"MTE2_AIV", aiv0 + "MTE2", "AIV-0"},
31	            {"VEC", aiv0 + "VEC", "AIV-0"},         {"MTE3", aiv0 + "MTE3", "AIV-0"},
32	            {"MTE2_AIV_1", aiv1 + "MTE2", "AIV-1"}, {"VEC_1", aiv1 + "VEC", "AIV-1"},
33	            {"MTE3_1", aiv1 + "MTE3", "AIV-1"},
34	        };
35	    }
36	
37	    struct PipelineSummaryRow {
38	        uint32_t core_id = 0;
39	        std::string unit;
40	        uint64_t total_cycles = 0;
41	        uint64_t active_start_cycle = 0;
42	        uint64_t active_end_cycle = 0;
43	        uint64_t active_cycles = 0;
44	        uint64_t busy_cycles = 0;
45	        uint64_t scalar_cycles = 0;
46	        uint64_t mte2_aic_cycles = 0;
47	        uint64_t mte2_aiv_cycles = 0;
48	        uint64_t mte1_cycles = 0;
49	        uint64_t cube_cycles = 0;
50	        uint64_t fixp_cycles = 0;
51	        uint64_t vec_cycles = 0;
52	        uint64_t mte3_cycles = 0;
53	    };
54	
55	    static uint64_t EventBusyCycles(const PipeEvent &event)
56	    {
57	        return event.stuck ? event.duration : (event.end_cycle - event.start_cycle);
58	    }
59	
60	    static bool EnsureParentDir(const std::string &path)
61	    {
62	        std::filesystem::path output_path(path);
63	        auto parent = output_path.parent_path();
64	        if (parent.empty()) {
65	            return true;
66	        }
67	
68	        std::error_code ec;
69	        std::filesystem::create_directories(parent, ec);
70	        if (ec) {
71	            std::cerr << "[perf_sim] Cannot create output directory: " << parent.string() << "\n";
72	            return false;
73	        }
74	        return true;
75	    }
76	
77	    static PipelineSummaryRow BuildPipelineSummaryRow(const PipeTimeline &timeline, uint32_t core_id,
78	                                                      const std::string &unit, const std::vector<std::string> &pipes)
79	    {
80	        std::unordered_map<std::string, uint64_t> busy_cycles;
81	        uint64_t active_start = std::numeric_limits<uint64_t>::max();
82	        uint64_t active_end = 0;
83	        for (auto &ev : timeline.events) {
84	            if (std::find(pipes.begin(), pipes.end(), ev.pipe_label) == pipes.end())
85	                continue;
86	            uint64_t busy = EventBusyCycles(ev);
87	            busy_cycles[ev.pipe_label] += busy;
88	            if (busy > 0) {
89	                active_start = std::min(active_start, ev.start_cycle);
90	                active_end = std::max(active_end, ev.end_cycle);
91	            }
92	        }
93	
94	        auto get = [&](const char *pipe) -> uint64_t {
95	            auto it = busy_cycles.find(pipe);
96	            return it == busy_cycles.end() ? 0 : it->second;
97	        };
98	
99	        PipelineSummaryRow row;
100	        row.core_id = core_id;
101	        row.unit = unit;
102	        row.total_cycles = timeline.total_cycles;
103	        row.active_start_cycle = active_start == std::numeric_limits<uint64_t>::max() ? 0 : active_start;
104	        row.active_end_cycle = active_end;
105	        row.active_cycles = active_end > row.active_start_cycle ? active_end - row.active_start_cycle : 0;
106	        row.scalar_cycles = get("Scalar");
107	        row.mte2_aic_cycles = get("MTE2_AIC");
108	        row.mte2_aiv_cycles = get("MTE2_AIV") + get("MTE2_AIV_1");
109	        row.mte1_cycles = get("MTE1");
110	        row.cube_cycles = get("CUBE");
111	        row.fixp_cycles = get("FIXP");
112	        row.vec_cycles = get("VEC") + get("VEC_1");
113	        row.mte3_cycles = get("MTE3") + get("MTE3_1");
114	        row.busy_cycles = row.scalar_cycles + row.mte2_aic_cycles + row.mte2_aiv_cycles + row.mte1_cycles +
115	                          row.cube_cycles + row.fixp_cycles + row.vec_cycles + row.mte3_cycles;
116	        return row;
117	    }
118	
119	    static std::vector<PipelineSummaryRow> BuildPipelineSummary(const SimReport &report)
120	    {
121	        std::vector<PipelineSummaryRow> rows;
122	        rows.reserve(report.num_cores * 3);
123	        auto append_core = [&](const PipeTimeline &timeline, uint32_t core_id) {
124	            rows.push_back(
125	                BuildPipelineSummaryRow(timeline, core_id, "AIC", {"Scalar", "MTE2_AIC", "MTE1", "CUBE", "FIXP"}));
126	            rows.push_back(BuildPipelineSummaryRow(timeline, core_id, "AIV0", {"MTE2_AIV", "VEC", "MTE3"}));
127	            rows.push_back(BuildPipelineSummaryRow(timeline, core_id, "AIV1", {"MTE2_AIV_1", "VEC_1", "MTE3_1"}));
128	        };
129	        if (report.num_cores == 1)
130	            append_core(report.timeline, 0);
131	        else
132	            for (uint32_t c = 0; c < report.num_cores; ++c)
133	                append_core(report.multi_timeline.per_core[c], c);
134	        return rows;
135	    }
136	
137	    static void AccumulateLogicalCoreStats(SimReport &report, uint32_t logical_cores)
138	    {
139	        for (uint32_t lc = 0; lc < logical_cores; ++lc) {
140	            report.instr_count += PtoRecorder::GetForCore(lc).size();
141	            report.sync_count += SyncRecorder::GetForCore(lc).size();
142	        }
143	    }
144	
145	    static void DropCrossCoreSync(std::vector<MergedEntry> &merged)
146	    {
147	        merged.erase(std::remove_if(merged.begin(), merged.end(),
148	                                    [](const MergedEntry &e) { return e.is_sync && e.sync.cross_core; }),
149	                     merged.end());
150	    }
151	
152	    static void SetCacheStats(SimReport &report, const L2CacheModel &cache)
153	    {
154	        report.cache_hits = cache.GetStats().hits;
155	        report.cache_misses = cache.GetStats().misses;
156	        report.cache_hit_rate = cache.GetStats().HitRate();
157	    }
158	
159	    static void RunSingleCoreSimulation(SimReport &report)
160	    {
161	        report.num_cores = 1;
162	        AccumulateLogicalCoreStats(report, VEC_CORES_PER_AIC);
163	
164	        auto merged = MergeRecordsForPhysicalCore(0);
165	        DropCrossCoreSync(merged);
166	        InlineSyncIntoMerged(merged);
167	
168	        auto queues = MakePipeQueues();
169	        std::vector<EventChannel> channels(TotalChannels());
170	        FillQueuesFromMerged(queues, channels, merged);
171	
172	        L2CacheModel cache;
173	        report.timeline = StepSimulate(queues, channels, cache);
174	        SetCacheStats(report, cache);
175	    }
176	
177	    static std::vector<CorePipeline> BuildCorePipelines(uint32_t num_cores)
178	    {
179	        std::vector<CorePipeline> core_pipelines(num_cores);
180	        for (uint32_t c = 0; c < num_cores; ++c) {
181	            core_pipelines[c].core_id = c;
182	            core_pipelines[c].queues = MakePipeQueues();
183	        }
184	        return core_pipelines;
185	    }
186	
187	    static void PrepareCoreMergedQueues(std::vector<CorePipeline> &core_pipelines,
188	                                        std::vector<std::vector<MergedEntry>> &per_core_merged,
189	                                        std::vector<EventChannel> &intra_channels,
190	                                        std::vector<EventChannel> &cross_channels)
191	    {
192	        for (uint32_t c = 0; c < core_pipelines.size(); ++c) {
193	            DropCrossCoreSync(per_core_merged[c]);
194	            InlineSyncIntoMerged(per_core_merged[c]);
195	            FillQueuesFromMerged(core_pipelines[c].queues, intra_channels, cross_channels, per_core_merged[c]);
196	        }
197	    }
198	
199	    static void RunMultiCoreSimulation(SimReport &report, uint32_t num_cores, uint32_t cross_core_channel_count)
200	    {
201	        report.num_cores = num_cores;
202	        AccumulateLogicalCoreStats(report, num_cores * VEC_CORES_PER_AIC);
203	
204	        auto per_core_merged = MergeRecordsPerCore(num_cores);
205	        auto core_pipelines = BuildCorePipelines(num_cores);
206	        std::vector<EventChannel> intra_channels(num_cores * EVENTS_PER_CORE);
207	        std::vector<EventChannel> cross_channels(cross_core_channel_count);
208	
209	        PrepareCoreMergedQueues(core_pipelines, per_core_merged, intra_channels, cross_channels);
210	
211	        L2CacheModel cache;
212	        report.multi_timeline = StepSimulateMultiCore(core_pipelines, intra_channels, cross_channels, cache);
213	        SetCacheStats(report, cache);
214	    }
215	
216	    SimReport Run(const std::string &op_name)
217	    {
218	        SimReport report;
219	        report.op_name = op_name;
220	        auto &cfg = GetConfig();
221	        if (cfg.block_dim <= 1) {
222	            RunSingleCoreSimulation(report);
223	        } else {
224	            RunMultiCoreSimulation(report, cfg.block_dim, cfg.cross_core_channel_count);
225	        }
226	        return report;
227	    }
228	
229	    // ── Pipeline table: rows=core, cols=pipe, cell=busy cycles ──
230	    static void PrintPipelineTable(const SimReport &report, std::ostream &os)
231	    {
232	        // Fixed column order for all pipelines across all cores
233	        const char *const pipe_names[] = {"Scalar", "MTE2(AIC)", "MTE1", "CUBE", "FIXP", "MTE2(AIV)", "VEC", "MTE3"};
234	        constexpr int kPipes = 8;
235	
236	        auto rows = BuildPipelineSummary(report);
237	
238	        // Header row
239	        os << "Pipeline     |";
240	        for (uint32_t c = 0; c < report.num_cores; ++c)
241	            os << " AIC-" << c << "   |";
242	        os << "\n";
243	        os << "-------------+";
244	        for (uint32_t c = 0; c < report.num_cores; ++c)
245	            os << "--------+";
246	        os << "\n";
247	
248	        // Data rows
249	        for (int p = 0; p < kPipes; ++p) {
250	            os << std::setw(12) << pipe_names[p] << " |";
251	            for (uint32_t c = 0; c < report.num_cores; ++c) {
252	                const auto &aic = rows[c * 3];
253	                const auto &aiv0 = rows[c * 3 + 1];
254	                const auto &aiv1 = rows[c * 3 + 2];
255	                const uint64_t values[kPipes] = {
256	                    aic.scalar_cycles,
257	                    aic.mte2_aic_cycles,
258	                    aic.mte1_cycles,
259	                    aic.cube_cycles,
260	                    aic.fixp_cycles,
261	                    aiv0.mte2_aiv_cycles + aiv1.mte2_aiv_cycles,
262	                    aiv0.vec_cycles + aiv1.vec_cycles,
263	                    aiv0.mte3_cycles + aiv1.mte3_cycles,
264	                };
265	                uint64_t v = values[p];
266	                if (v == 0) {
267	                    os << "       - |";
268	                } else {
269	                    os << std::setw(7) << v << " |";
270	                }
271	            }
272	            os << "\n";
273	        }
274	        os << "\n";
275	        os << "Note: AIV pipeline rows sum AIV0 and AIV1. Use pipeline_summary.csv for per-AIV active/busy cycles.\n\n";
276	    }
277	
278	    static void PrintText(const SimReport &report, std::ostream &os = std::cout)
279	    {
280	        os << "===== Perf-Sim Report: " << report.op_name << " =====\n";
281	        os << "Cores        : " << report.num_cores << "\n";
282	        os << "Instructions : " << report.instr_count << "\n";
283	        os << "Sync events  : " << report.sync_count << "\n";
284	
285	        uint64_t total_cycles =
286	            (report.num_cores == 1) ? report.timeline.total_cycles : report.multi_timeline.total_cycles;
287	        os << "Total cycles : " << total_cycles << "\n";
288	        os << "L2 Cache hits: " << report.cache_hits << "  misses: " << report.cache_misses
289	           << "  hit rate: " << report.cache_hit_rate << "%\n\n";
290	
291	        PrintPipelineTable(report, os);
292	
293	        os << "===== End Report =====\n";
294	    }
