45	template <typename T>
46	inline constexpr bool IsMadSupportedDType()
47	{
48	    return std::is_same_v<T, float> || std::is_same_v<T, float32_t> || std::is_same_v<T, half> ||
49	           std::is_same_v<T, float16_t>;
50	}
