60	template <typename CType, typename AType, typename BType>
61	inline bool TryEstimateMadCycles(uint64_t m, uint64_t k, uint64_t n, uint64_t& cycles)
62	{
63	    (void)sizeof(CType);
64	    (void)sizeof(BType);
65	    if constexpr (!IsMadSupportedDType<AType>()) {
66	        return false;
67	    }
68	
69	    if (m == 0 || k == 0 || n == 0) {
70	        return false;
71	    }
72	
73	    constexpr uint64_t kHeadCycles = 6;
74	    constexpr uint64_t kMTile = 16;
75	    constexpr uint64_t kNTile = 16;
76	    constexpr uint64_t kKFractalBytes = 32;
77	    constexpr uint64_t kABytes = sizeof(AType);
78	    constexpr uint64_t kKTile = (kABytes > 0) ? (kKFractalBytes / kABytes) : 0;
79	    if (kKTile == 0) {
80	        return false;
81	    }
